const t1 = `workspace "Test" {
    model {
        softwareSystem "Order Platform" "Accepts orders" {
            container "Web Store" "order-web" "Web" "Browser-based storefront"
            container "Order API" "order-api" "Service" "REST API"
        }
    }
}`;
const t2 = `workspace "Test" {
    model {
        element "Widget" "A generic element"
    }
}`;
const t3 = `workspace "Test" {
    model {
        softwareSystem "Order Platform" "Accepts orders" {
            container "Web Store" "order-web" "Web" "Browser-based storefront" {
                component "Cart" "cart" "Class" "Holds items"
            }
        }
    }
}`;
const [r1, r2, r3] = await Promise.allSettled([
  tools.structurizr.parse({ dsl: t1 }),
  tools.structurizr.parse({ dsl: t2 }),
  tools.structurizr.parse({ dsl: t3 }),
]);
const summarize = (r) => r.status === "fulfilled"
  ? JSON.stringify(r.value.model, null, 1).slice(0, 1500)
  : String(r.reason);
return { nested_container: summarize(r1), element: summarize(r2), nested_component: summarize(r3) };

